protocolTypes.tsDefinition:
| {
    type: 'capability_activation';
    /** Which engine capability this frame is about. Widened: the contract declares no payload. */
    capability: EngineCapabilityId | (string & {});
    /** Where in activation it got to. Widened for the same reason. */
    stage: CapabilityActivationStage | (string & {});
    /** MEASURED: present if and only if `stage === 'unavailable'`. Absent otherwise. */
    reason?: CapabilityUnavailableReason | (string & {});
  }
